174			swapIndex  string
175			field      string
176		}{
177			{
178				"missing gasPrice",
179				"{\"chainId\":\"1\",\"blockHash\":\"0x\",\"blockNumber\":1,\"swaps\":[{\"TxHash\":\"0x1\",\"Pool\":\"p1\",\"Trader\":\"t\",\"In\":1,\"Out\":1,\"Index\":0}]}",
180				1, "swaps[0]", "GasPrice",
181			},
182			{
183				"null gasPrice",
184				"{\"chainId\":\"1\",\"blockHash\":\"0x\",\"blockNumber\":1,\"swaps\":[{\"TxHash\":\"0x1\",\"Pool\":\"p1\",\"Trader\":\"t\",\"In\":1,\"Out\":1,\"GasPrice\":null,\"Index\":0}]}",
185				1, "swaps[0]", "GasPrice",
186			},
187			{
188				"missing in",
189				"{\"chainId\":\"1\",\"blockHash\":\"0x\",\"blockNumber\":1,\"swaps\":[{\"TxHash\":\"0x1\",\"Pool\":\"p1\",\"Trader\":\"t\",\"Out\":1,\"GasPrice\":1,\"Index\":0}]}",
190				1, "swaps[0]", "In",
191			},
192			{
193				"null out",
194				"{\"chainId\":\"1\",\"blockHash\":\"0x\",\"blockNumber\":1,\"swaps\":[{\"TxHash\":\"0x1\",\"Pool\":\"p1\",\"Trader\":\"t\",\"In\":1,\"Out\":null,\"GasPrice\":1,\"Index\":0}]}",
195				1, "swaps[0]", "Out",
196			},
197			{
198				"null index",
199				"{\"chainId\":\"1\",\"blockHash\":\"0x\",\"blockNumber\":1,\"swaps\":[{\"TxHash\":\"0x1\",\"Pool\":\"p1\",\"Trader\":\"t\",\"In\":1,\"Out\":1,\"GasPrice\":1,\"Index\":null}]}",
200				1, "swaps[0]", "Index",
201			},
202			{
203				"missing index on later line after blanks",
204				"{\"chainId\":\"1\",\"blockHash\":\"0x1\",\"blockNumber\":1,\"swaps\":[]}\n\n" +
205					"{\"chainId\":\"1\",\"blockHash\":\"0x2\",\"blockNumber\":2,\"swaps\":[{\"TxHash\":\"0x1\",\"Pool\":\"p1\",\"Trader\":\"t\",\"In\":1,\"Out\":1,\"GasPrice\":1}]}",
206				3, "swaps[0]", "Index",
207			},
208			{
209				"missing gas on second swap of last line without trailing newline",
210				"\n" +
211					"{\"chainId\":\"1\",\"blockHash\":\"0x\",\"blockNumber\":1,\"swaps\":[" +
212					swapJSON("0xfront", 0, `"GasPrice":30,`) + "," +
213					`{"TxHash":"0xvic","Pool":"p1","Trader":"u","In":1,"Out":1,"Index":1}` +
214					"]}",
215				2, "swaps[1]", "GasPrice",
216			},
217		}
218		for _, tc := range cases {
219			t.Run(tc.name, func(t *testing.T) {
220				dir := t.TempDir()
