type rawVersionArchiveDoc struct {
	Records  []record          `json:"records"`
	Versions []json.RawMessage `json:"versions"`
	Reviews  []ReviewObject    `json:"reviews"`
}

// replayArchiveDoc mirrors the archive file the way a replay reads it. It
// embeds rawVersionArchiveDoc, so every registered version is kept as its
// raw stored document: a wrong-typed or null field in one version is that
// version's corruption, judged on its own by intactVersion, rather than
// failing the whole-archive decode or silently decoding to a zero value.
// Suppressions and alert records are decoded normally: replay never judges
// them, but it rewrites the archive atomically when it adds blocks, so the
// commit must round-trip them untouched.
type replayArchiveDoc struct {
	rawVersionArchiveDoc
	Suppressions []Suppression      `json:"suppressions"`
	AlertRecords []ProcessingRecord `json:"alerts"`
}

// archiveData returns the fully decoded view the rest of a replay works
// with. Each raw version document is decoded independently; a corrupt
// sibling whose own document is malformed JSON would fail here only once it
// matters, while the replay's selected version is always proven intact from
// its raw bytes first via intactVersion.
func (d replayArchiveDoc) archiveData() (data archiveData) {
	data.Records = d.Records
	data.Reviews = d.Reviews
	data.Suppressions = d.Suppressions
	data.AlertRecords = d.AlertRecords
	data.EnabledVersion = d.EnabledVersion
	data.Versions = make([]RuleVersion, 0, len(d.Versions))
	for _, raw := range d.Versions {
		var v RuleVersion
		if err := json.Unmarshal(raw, &v); err == nil {
			data.Versions = append(data.Versions, v)
		}
	}
	return data
}

