// written before rule versions existed have no marker and run the built-in
// rules.
func (d archiveData) enabledVersion() (RuleVersion, error) {
	if d.EnabledVersion == "" {
		return BuiltinVersion(), nil
	}
	return findVersion(d, d.EnabledVersion)
}

