	legacy := `{"records":[{"chainId":"1","blockHash":"0xleg","blockNumber":5,` +
		`"swaps":[{"TxHash":"0xfront","Pool":"p1","Trader":"bot","In":500,"Out":480,"GasPrice":90,"Index":0},` +
